package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Set;

/**
 * Business-day helper for owner registration. The effective registration date must fall on a
 * business day: when it lands on a Saturday, Sunday or a listed public holiday it is rolled forward
 * to the next non-holiday business day. Applies to the effective registration date whether supplied
 * in the request or defaulted to the server date, and every value derived from that date
 * (membership-number year, daily create-limit) must use the adjusted date.
 */
final class BusinessDay {

    /** Fixed public-holiday calendar; a date landing on any of these rolls forward. */
    private static final Set<LocalDate> HOLIDAYS = Set.of(
            LocalDate.of(2026, 1, 1),
            LocalDate.of(2026, 1, 26),
            LocalDate.of(2026, 4, 25),
            LocalDate.of(2026, 12, 25),
            LocalDate.of(2026, 12, 28));

    private BusinessDay() {
    }

    /**
     * Roll a weekend or public-holiday date forward to the next non-holiday business day; a business
     * day that is not a holiday is returned unchanged.
     */
    static LocalDate adjust(LocalDate date) {
        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
                || HOLIDAYS.contains(date)) {
            date = date.plusDays(1);
        }
        return date;
    }
}

