1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	/**
8	 * Business-day helper for owner registration. The effective registration date must fall on a
9	 * business day: when it lands on a Saturday, Sunday or a listed public holiday it is rolled forward
10	 * to the next non-holiday business day. Applies to the effective registration date whether supplied
11	 * in the request or defaulted to the server date, and every value derived from that date
12	 * (membership-number year, daily create-limit) must use the adjusted date.
13	 */
14	final class BusinessDay {
15	
16	    /** Fixed public-holiday calendar; a date landing on any of these rolls forward. */
17	    private static final Set<LocalDate> HOLIDAYS = Set.of(
18	            LocalDate.of(2026, 1, 1),
19	            LocalDate.of(2026, 1, 26),
20	            LocalDate.of(2026, 4, 25),
21	            LocalDate.of(2026, 12, 25),
22	            LocalDate.of(2026, 12, 28));
23	
24	    private BusinessDay() {
25	    }
26	
27	    /**
28	     * Roll a weekend or public-holiday date forward to the next non-holiday business day; a business
29	     * day that is not a holiday is returned unchanged.
30	     */
31	    static LocalDate adjust(LocalDate date) {
32	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
33	                || HOLIDAYS.contains(date)) {
34	            date = date.plusDays(1);
35	        }
36	        return date;
37	    }
38	}
