10	/**
11	 * Rejects a create-owner request once {@link #DAILY_LIMIT} or more owners have already been created
12	 * for the request's adjusted business day, counting existing owners whose {@code registrationDate}
13	 * equals that day. The day is the effective registration date (supplied in the request or defaulted
14	 * to the server date) rolled forward off any weekend to the next Monday, matching how
15	 * {@link BuildOwner} stores it. Runs before the owner is built and saved. At capacity the request is
16	 * rejected via {@link DailyLimitExceededException}, which the global handler turns into a 429.
17	 */
18	public class RejectOverDailyLimit {
19	
20	    /** Maximum owners that may be created in a single day; the request is rejected once this many exist. */
21	    static final int DAILY_LIMIT = 100;
22	
23	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
24	            throws DailyLimitExceededException {
25	        LocalDate effective = request.getRegistrationDate() != null ? request.getRegistrationDate() : LocalDate.now();
26	        LocalDate day = BusinessDay.adjust(effective);
27	        int count = 0;
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (day.equals(existing.getRegistrationDate())) {
30	                count++;
31	            }
32	        }
33	        if (count >= DAILY_LIMIT) {
34	            throw new DailyLimitExceededException(DAILY_LIMIT);
35	        }
36	    }
37	}
